window.studyLocaleData = {"groups": [{"id": "knowledge", "title": "知识库与资料助手", "items": [{"title": "Chat with Docs：文档问答", "quick": "从文档更新到引用校验，回答有据可查。", "principle": "先校验访问权限，再检索资料；没有证据就明确拒答。", "sub": "从文档入库、切分和更新，到检索、生成、引用，再到错误定位和发布评估。重点是来源不能丢，权限不能越，答错了要知道错在哪。", "flow": ["文档入库", "解析、切分与索引", "按权限检索", "带引用的回答"], "problem": "让用户基于文档提问。文档会更新，不同用户能看的内容也不同，因此系统既要找对资料，也要确保回答有出处、检索不越权。", "architecture": "文档先解析成内容块，保留文档 ID、页码、版本和权限信息，再分别建立向量索引和关键词索引。查询时先按用户权限过滤，召回候选片段后做重排，最后让模型根据片段作答并给出引用。文档新增、修改或删除后，通过变更队列更新索引，同时清理过期缓存。", "decisions": "<strong>为什么用混合检索：</strong>关键词检索适合查术语、编号等精确信息，向量检索更擅长找意思相近的内容。两者结合能互补，但索引维护和调参更复杂。<strong>文档怎么切：</strong>按章节结构切分更容易保留语义，固定窗口更简单；需要比较上下文是否够用、召回是否准确。<strong>更新多快才够：</strong>增量更新能减少过时回答，但要保证各份索引的版本一致。权限必须由系统执行，不能让模型自行判断；证据不足时应拒答。", "impact": "回答附带依据，检索遵守访问权限。重排和引用检查会增加延迟与成本，需要用评估判断是否值得。记录每个阶段的输入和结果，才能分清是没检索到、排错了，还是模型答错了。", "evaluation": "准备一组带标准答案和原文出处的问题，加入资料缺失、文档更新、越权访问等案例。分别检查解析、召回、重排和生成，避免只给整个系统一个总分。比较召回率、引用是否支持回答、回答质量、延迟和成本；权限隔离与事实依据是发布前必须通过的检查。"}, {"title": "资料研究助手", "quick": "研究结论有依据，资料缺口与冲突也清楚可见。", "principle": "把证据覆盖与未解决冲突作为交付内容，不只检查引用。", "sub": "围绕研究问题组织证据，检查覆盖与冲突，形成可审阅的报告。", "flow": ["研究任务", "问题与证据", "检查缺口和冲突", "审阅报告"], "problem": "文档问答解决一个问题，研究报告需要覆盖整项任务。即使每条引用都准确，仍可能漏掉关键问题或相反证据。系统需要让这些缺口清楚可见。", "architecture": "先确认研究任务与验收标准，再拆成子问题。证据表记录问题、结论、原文段落、版本、权限与冲突。针对缺口进行有预算上限的检索和核查，持续保存任务状态。证据足够或预算用尽即停止，报告同时列出结论、反面证据和未解决问题，由人审阅。音频作为可选输出，基于已批准报告生成并保留来源。", "decisions": "<strong>直接 RAG 还是研究流程：</strong>单个明确问题优先检索作答；需要覆盖多个关联问题时，再增加规划与修订。<strong>覆盖还是搜索数量：</strong>依据验收标准判断哪些缺口值得继续查，不追求更多来源。<strong>审阅还是自动定论：</strong>保留未解决的分歧，不让写作模块擅自选边。缓存绑定资料版本和权限，报告审阅与音频生成独立调度。", "impact": "问题与证据逐项对应，审阅者可以快速看出哪些结论有依据、哪些信息缺失、哪些仍有争议。限制搜索预算并保存任务状态，让交付进度与成本可检查。与直接 RAG 对照，才能判断额外流程是否减少了返工。", "evaluation": "固定研究任务、资料、模型与预算，对比直接 RAG 和研究流程。按专家制定的标准检查问题覆盖、结论依据、遗漏的反面证据、冲突披露、人工修订量、延迟与成本。加入资料缺失、文档更新、访问受限和任务中断场景。音频脚本先与已批准报告核对，再进入语音合成。"}]}, {"id": "agents", "title": "事实核查", "items": [{"title": "客服 Agent", "quick": "问答与执行分开设计，业务操作受权限约束。", "principle": "业务操作先校验权限；退款、改订单等请求按规则确认或转人工。", "sub": "从客服目标推导系统架构，串起工具调用、会话状态和转人工；先用评估定位问题，再考虑提示词、RAG、SFT 或偏好优化。", "flow": ["识别请求与业务规则", "校验权限与操作参数", "必要的人工确认", "执行留档／转人工"], "problem": "客服不只是回答准确。有些请求需要查订单、改信息或处理退款，系统必须分清哪些操作可以自动完成，哪些需要用户确认，哪些必须转人工。", "architecture": "先把支持范围拆成意图、可用工具和转人工条件。会话状态单独保存，不只依赖模型上下文。回答前检索业务规则，调用工具前校验参数和权限；敏感或不可逆操作走确认流程。写操作带幂等键，避免重复执行。转人工时附上对话、相关依据、已尝试的操作和未解决的问题。", "decisions": "<strong>工作流还是自主 Agent：</strong>规则明确的操作用固定流程，含糊请求再给模型有限的判断空间。<strong>先改检索还是训练模型：</strong>先用 evals 找到具体问题，优先修提示词和 RAG。确实需要训练时，再使用获授权、已脱敏、结果核实过的对话做 SFT；偏好标签足够可靠，才考虑偏好优化。无论怎么训练，运行时的授权检查都必须保留。", "impact": "权限校验、操作确认和幂等处理，目的是减少越权和重复操作，但也会增加交互步骤。评估时要同时看安全和问题解决质量。交接信息完整，人工接手时就不必让用户从头解释。", "evaluation": "调优前先准备客服案例，覆盖答案正确性、业务规则、工具和参数选择、问题解决、转人工质量。模拟工具故障和 prompt injection。用留出的测试案例加人工审核，对比提示词、RAG、SFT 和偏好优化；业务操作违规单独统计，不能被整体回答分数掩盖。"}, {"title": "旅行规划 Agent", "quick": "让交通、住宿和活动组成满足约束的行程。", "principle": "多 Agent 共享同一份计划；预订前刷新报价并由用户确认。", "sub": "研究多 Agent 如何分工并收敛到一致方案，以及长时间运行任务中的记忆、计划状态、外部报价、失败恢复和任务级评估。", "flow": ["收集需求与限制", "分头查交通住宿活动", "合并并校验行程", "刷新报价、用户确认"], "problem": "把交通、酒店和活动组合成满足时间、预算和偏好的行程。难点不只是各自找到好选项，还要保证它们放在一起可行；查到价格也不等于已经订好。", "architecture": "由协调 Agent 分派交通、住宿和活动查询任务。共享计划保存约束、候选方案、依赖关系、报价时间和冲突，并记录版本。协调 Agent 按统一目标合并方案，满足约束或用完迭代预算就停止。过程中保存工具结果和检查点，任务中断后能继续；用户确认前重新获取报价。", "decisions": "<strong>多 Agent 是否值得：</strong>并行查询可能更快，但会增加协调成本，也可能采用不一致的假设。需要限定轮数，以同一份计划为准。<strong>记住偏好还是服从当前要求：</strong>长期记忆只保存用户认可的偏好，与本次任务状态分开。临时查询失败可以退避重试；预订必须先确认，写操作用幂等机制防止重复下单。", "impact": "共享计划让用户看得到进展和冲突。检查点避免长任务重复从头执行，迭代上限控制耗时与费用。重新查价和确认会多一步操作，但能避免按过期报价下单。", "evaluation": "用偏好冲突、无库存、报价变化、工具超时和断点恢复等场景测试。检查行程是否可执行、是否满足约束、报价是否仍有效、方案能否收敛、恢复后状态是否正确。与单 Agent 比较任务完成情况、耗时、工具调用量和成本；单独检查是否跳过用户确认。"}, {"title": "事实核查 Agent", "quick": "按事实检索、核对和引用，不把重复报道当独立证据。", "principle": "证据足够才给结论；证据不足或预算耗尽，明确说明限制。", "sub": "从核查目标出发，设计搜索、证据判断和引用流程，分层评估模型与 Agent，并将审核过的错误反馈到后训练数据。", "flow": ["拆分待核查事实", "搜索并去重", "判断证据是否支持", "给结论、引用与不确定性"], "problem": "核查带时间背景的事实，区分“有证据支持”“有证据反驳”和“目前证据不足”。不能把多篇转载算成多份独立证据，也不能因为搜不到就断言错误。", "architecture": "先明确待核查的事实、涉及的实体和时间范围，再制定有预算的搜索计划。优先查一手来源，分别记录发布时间与事件时间，对重复报道去重。逐条判断证据是否相关、是否支持结论，输出引用和不确定性。运行时控制搜索深度、重试次数，以及何时停止。", "decisions": "<strong>继续查还是停止：</strong>补充检索可能找到关键证据，也会增加等待和费用。达到证据标准就结束；预算耗尽仍不清楚，就说明证据不足。<strong>来源多还是来源独立：</strong>转载不能重复计票。结论应基于可核对的原文，而不是几段看似一致的生成内容；来源冲突无法解决时交人工复核。", "impact": "用户能顺着引用检查判断依据，也知道哪些问题还没有答案。搜索预算限制等待时间和费用；“证据不足”是有效结果，不能为了给答案而制造确定性。分阶段记录结果，方便查清错误出在哪一步。", "evaluation": "分别看检索相关性、证据是否支持判断、引用是否正确、置信度是否可信，以及整项任务是否完成。加入过期信息、被操纵的来源、相互冲突的报道和预算耗尽案例。审核后的错误与困难负例进入版本化训练数据；按主题和时间划分测试集，检查泛化并避免数据泄漏。"}]}, {"id": "multimodal", "title": "多模态与内容生成", "items": [{"title": "多模态助手", "quick": "把图像理解、排队延迟与显存预算放在一起设计。", "principle": "按任务选择图片分辨率与 GPU 资源，比较理解质量和推理成本。", "sub": "拆解图文输入到回答的端到端链路，研究图像编码、上下文、缓存、GPU 路由与调度，以及安全、可观测性和迭代。", "flow": ["接收图文输入", "图像编码与上下文组装", "GPU 路由与推理", "安全检查、流式回答"], "problem": "让助手处理图文对话，同时把响应时间和资源使用控制在合理范围内。答错时还要能区分：是图片没看懂，还是预处理、排队或服务链路出了问题。", "architecture": "先校验和预处理图片，再做图像编码，将视觉 token、文本和相关对话组装成上下文。按模型能力和可用显存路由请求，安排 prefill 与 decode，检查输出安全后流式返回。预处理、编码、排队、推理和安全检查分别记录耗时与结果。", "decisions": "<strong>图片细节与算力：</strong>更高分辨率可能有助于 OCR 和细节判断，也会消耗更多视觉 token 和显存。<strong>缓存复用与隔离：</strong>编码缓存要同时考虑图片内容、编码器版本和访问权限。<strong>吞吐与响应速度：</strong>batching 提升吞吐，但等批次会增加延迟。扩缩容结合队列长度、处理耗时和预热容量上限，不能只看 GPU 利用率。", "impact": "分辨率和路由直接影响回答质量、等待时间与 GPU 成本。分阶段追踪能区分理解错误和服务延迟，带权限的缓存及安全检查则保护用户隐私和信任。", "evaluation": "按 OCR、空间关系、图文对应、多图比较和不安全输入分别评估。观察每段耗时、显存压力、排队、缓存与回答质量。用脱敏 traces 定位问题，将失败案例加入离线 evals，发布前比较模型和调度策略的变化。"}, {"title": "文生视频系统", "quick": "视频生成按长任务管理，失败后尽量复用已完成结果。", "principle": "按算力预算接收任务，用持久化状态支持排队、取消和恢复。", "sub": "围绕视频质量拆解生成链路，重点考虑任务准入、GPU 预算、异步调度、失败恢复与成本优化。", "flow": ["检查需求、估算成本", "任务准入与排队", "分阶段 GPU 生成", "质量安全检查、交付"], "problem": "把提示词生成连贯视频，同时控制 GPU 花费、等待时间和失败重试。任务昂贵且耗时较长，不能照搬即时问答的处理方式。", "architecture": "校验提示词和输出要求，估算计算成本，只接纳用户预算和集群容量允许的任务。用持久化状态机管理异步任务，将条件处理、生成、解码和安全校验分阶段调度。有条件时保存检查点，提供进度和取消入口；某一阶段失败时尽量复用已完成的结果。", "decisions": "<strong>质量与容量：</strong>时长、分辨率、帧数和采样步数都影响计算量，模型和推理参数应放在同一预算下比较。<strong>吞吐与排队：</strong>相似任务分桶，限制队列长度，为不同服务等级预留有上限的容量。检查点只有在恢复收益超过存储和 I/O 开销时才值得保存；故障重试与用户要求重新生成，需要分开处理。", "impact": "准入和排队规则让用户知道为什么要等、预计占用多少资源。持久化状态支持查进度、取消和恢复。选质量配置时，不只看画面效果，也要看 GPU 时间和每个合格输出的成本。", "evaluation": "使用固定提示词集，人工比较提示遵循、时序连贯、运动、画面瑕疵和安全。模拟节点故障、取消和重试用尽。记录 GPU 时间、排队时长、完成率与合格输出成本；先找生成或解码瓶颈，再决定怎么优化。"}]}, {"id": "reasoning", "title": "推理与编程", "items": [{"title": "推理模型", "quick": "比较训练投入与推理预算，而不以回答长度判断效果。", "principle": "额外推理是否值得，要看可验证的正确率提升与计算成本。", "sub": "从基础模型到指令对齐、偏好对齐与推理训练，重点分析思维链、可验证奖励和 test-time compute 如何改变算力预算。", "flow": ["基础模型", "指令与偏好对齐", "推理训练", "按预算分配推理计算"], "problem": "提高复杂任务的正确率，同时避免一个误区：让模型想更久、写更长，就一定会更准。", "architecture": "从预训练模型出发，用监督指令数据训练任务遵循，再比较偏好对齐方法。在结果可验证的任务上，用核验后的结果构造奖励，并检查奖励是否可靠。推理阶段为思考或多候选采样设预算，有条件时验证结果，最后给用户简洁答案和必要解释。", "decisions": "<strong>训练时投入还是推理时投入：</strong>训练更强的模型，与每次请求多算一些，成本结构和延迟影响不同。<strong>过程监督还是结果奖励：</strong>思维链数据可能有噪声；验证器不可靠时，结果奖励也可能被钻空子。比较固定推理预算与按难度路由，评估答案是否正确、解释是否有用，不把隐藏推理过程当作正确性的证明。", "impact": "推理预算把质量、等待时间和推理费用联系起来。独立验证器用来判断多算是否真有收益。用户需要的是正确且能明确说明不确定性的答案，不是尽可能长的解释。", "evaluation": "用独立验证器评估留出的数学、代码和受约束推理题，并排查训练数据与测试集的重合。比较不同预算下的正确率、置信度校准、延迟和计算量。检查奖励投机，也检查简单题是否退步；最终判断额外推理的收益能否覆盖成本。"}, {"title": "AI 编程助手", "quick": "快速补全与受控代码执行采用不同的处理链路。", "principle": "补全走低延迟链路；Agent 修改代码需要权限、检查和人工审核。", "sub": "参考 AI IDE 的工作方式，研究代码检索、上下文组装、Agent 执行、权限管理和改动验证，并兼顾补全延迟与系统评估。", "flow": ["理解 IDE 中的任务", "检索并组装代码上下文", "受控执行与修改", "展示 diff、运行检查"], "problem": "既要让补全不打断写代码的节奏，也要让复杂任务中的 Agent 不越过仓库和执行权限边界，改动仍由开发者审核。", "architecture": "IDE 扩展读取当前编辑位置和用户明确提供的任务信息。代码库索引结合符号、关键词与语义检索，组装上下文时遵守忽略规则和敏感文件限制。行内补全使用独立低延迟链路；Agent 循环负责规划修改、请求必要权限，在隔离环境跑检查，最后交付可审查的代码差异。", "decisions": "<strong>上下文是否够新：</strong>增量索引减少读到旧代码的问题，但需要按版本清理失效内容。<strong>补全要快还是上下文要多：</strong>补全先用小范围本地上下文，并支持取消；复杂任务再扩大检索。<strong>Agent 能做多少：</strong>命令允许列表、网络边界、人工审核与回滚一起设计。测试通过是证据之一，不代表改动完全正确。", "impact": "补全和 Agent 分开，避免长任务拖慢编辑。受限工具和可审查的代码差异 保留开发者的控制权；检索与执行记录 帮助解释改错的原因。任务正确性、延迟与是否遵守权限边界必须一起评估。", "evaluation": "获得用户同意后再记录补全延迟和采纳情况。用隔离的编程任务检查补丁正确性、测试回归、修改范围和任务完成。覆盖仓库中的 prompt injection、机密文件访问和权限绕过；分别记录漏检索、工具失败和验证遗漏，用来定位问题并改进系统。"}]}], "foundation": "<div class=\"group-title\"><h3>推理服务与资源调度</h3></div><details id=\"inference-details\"><summary><div class=\"study-title\"><h4>LLM 服务与容量规划</h4><p class=\"scope-preview\">各项目共用的工程基础</p><p class=\"quick-summary\">延迟、吞吐与 GPU 成本，决定 Agent 工作流的可行范围。</p></div><span class=\"disclosure-arrow\" aria-hidden=\"true\"></span></summary><div class=\"study-body\"><p>跟踪 API 鉴权、请求准入、分词、prefill、decode 到流式输出的完整过程。结合模型权重、KV cache 增长、GPU 显存余量和请求长度，估算可支持的并发。</p><p>围绕延迟与吞吐目标，比较 continuous batching、缓存复用和调度策略。评估多 GPU 下的张量并行与流水线并行，明确通信开销、显存容量和运维复杂度的取舍。</p><div class=\"foundation-topics\">请求与 token · KV cache 与显存 · batching 与调度 · 多 GPU 并行</div></div></details>", "contexts": {"study-docs": {"source": "gtsp-delivery", "sourceLabel": "GTSP 文档问答", "bridge": "GTSP 文档问答：资料权限、版本与回答依据", "connection": "GTSP 的文档问答接入，是这套设计的起点。回答与原始资料必须遵守同一套权限。后续方案进一步处理版本更新、检索质量和来源级 evals。", "can": "检索已授权资料，依据原文回答。", "stop": "不越权读取资料；找不到依据时，不补写事实。", "human": "知识负责人处理规则冲突，并批准资料更新。"}, "study-research": {"source": "gtsp-delivery", "sourceLabel": "GTSP 文档问答", "bridge": "GTSP 文档问答经验，为完整研究任务提供起点", "connection": "GTSP 的工作覆盖公司文档问答与受控业务请求。这里规划的交付单位更大：围绕多个研究问题，按覆盖标准收集证据，形成能看清缺口和分歧的报告。", "can": "规划有预算上限的研究任务，跟踪证据覆盖，生成附来源的报告。", "stop": "搜索达到预算即停止；不补造依据，不隐去尚未解决的冲突。", "human": "研究者确认任务范围，复核关键冲突，对外使用前批准报告。", "progression": [["已有经验", "GTSP 的文档问答与业务工具接入。"], ["下一步设计", "拆分研究问题，建立证据表，按缺口检索，再审阅完整报告。"], ["验证重点", "使用固定资料对比直接 RAG，检查覆盖、依据、人工修订量与成本。"]]}, "study-support": {"source": "gtsp-delivery", "sourceLabel": "GTSP 客服接入", "bridge": "GTSP 客服接入：业务操作的权限与恢复", "connection": "退款与订单修改接入，让“理解请求”和“获准执行”成为两件独立的事。后续设计围绕这条边界，细化权限校验、action gate 和失败恢复。", "can": "识别请求、检索规则，提出参数完整的工具调用。", "stop": "不绕过权限；执行结果不明时，不盲目重试。", "human": "不可逆操作由指定负责人批准。失败无法解决时，带上下文转人工。"}, "study-trip": {"source": "trip-delivery", "sourceLabel": "Remex 旅行规划", "bridge": "旅行规划交付：研究分工与行程一致性", "connection": "已交付的旅行规划把偏好转成行程约束。下一步研究并行检索是否能改善方案，同时避免各自假设不一致，以及重复预订。", "can": "研究候选方案，汇总到同一版本的行程。", "stop": "不把估算当实时报价，不把行程草案当预订结果。", "human": "用户确认方案取舍；预订或付款由指定负责人批准。"}, "study-fact": {"source": "analytics-project", "sourceLabel": "Twitter 数据分析", "bridge": "Twitter 数据分析：数据时效与证据核查", "connection": "Twitter 项目积累了 ETL、存储与缓存的实现经验。这个提案把数据时间带入事实核查，重点检查来源是否独立、证据是否仍然有效。", "can": "拆分待核查的说法，检索来源，判断证据是否支持结论。", "stop": "不把转载当独立证据；达到检索预算后停止。", "human": "审核者处理来源冲突，并确认用于重要决策的结论。"}, "study-multimodal": {"source": "commerce-project", "sourceLabel": "SpringCloud 电商平台", "bridge": "电商搜索：图文检索与商品权限", "connection": "SpringCloud 平台已有商品搜索、CDC 与权限控制。下一步加入图片输入，仍沿用商品更新与访问规则，让视觉理解接得上真实商品数据。", "can": "理解图文需求，检索有权访问的商品并说明匹配依据。", "stop": "不凭图片推断实时库存，不因匹配成功就创建订单。", "human": "用户确认商品与购买；图片含义不明确时由人核对。"}, "study-video": {"source": "remex", "sourceLabel": "Remex 视频 Agent", "bridge": "文生视频开发：任务状态、预算与恢复", "connection": "视频 Agent 正在开发。架构方案借鉴 Cloud Crafters 的部署与监控经验，先明确任务状态、算力预算和恢复方式，再扩展生成功能。", "can": "在已批准的预算内排队生成，展示进度与失败状态。", "stop": "不突破算力预算，不把失败任务标记为已交付。", "human": "不可逆操作由指定负责人批准；客户在发布前确认成片。"}, "study-reasoning": {"source": "trip-delivery", "sourceLabel": "Remex 行程约束", "bridge": "旅行约束检查：推理投入是否值得", "connection": "旅行规划的正确性可以落到具体约束上。这个提案选择可验证的任务，比较增加推理预算是否值得付出更多耗时与算力。", "can": "在限定预算内推理，用独立规则检查候选答案。", "stop": "不把回答长度或模型自信当作正确性证明。", "human": "审核者检查验证规则的盲区，并批准重要决策。"}, "study-coding": {"source": "cloud-crafters", "sourceLabel": "Cloud Crafters 工程交付", "bridge": "工程交付经验：可审阅的 Agent 代码改动", "connection": "Cloud Crafters 的工作覆盖应用开发、IAM 与 CI/CD。这个提案把交付边界带入编程助手：按权限读取代码、隔离运行检查、提交可审查的 diff。", "can": "读取授权代码，提出修改，在隔离环境运行允许的检查。", "stop": "不读取密钥，不自行扩大命令权限，不自动部署。", "human": "开发者审查 diff，并批准合并、部署和权限变更。"}}, "labels": {"STUDIES": "个案例", "Decision principle": "核心判断", "Architecture design study / proposed approach": "系统设计方案", "Product implications below are design intent, not measured outcomes.": "预期收益与代价属于设计判断，尚无实测数据。", "Proposed architecture flow": "架构流程图", "Study scope": "设计范围", "Problem": "用户问题", "Architecture": "架构方案", "Decisions & trade-offs": "关键决策与权衡", "Product implications": "预期收益与代价", "Evaluation plan": "Evals 计划", "In development / architecture notes": "开发中 / 架构笔记", "Completed work / architecture notes": "已完成工作 / 架构笔记", "The notes retain architecture analysis and evaluation plans; individual design components and intended benefits are not claims of deployed implementation or measured results.": "系统方案与评估计划。实际交付范围以项目经历为准，预期收益属于设计判断。", "Design study · not implemented": "独立设计研究 · 未上线", "Proposed support paths": "客服处理路径 · 设计方案", "Read-only questions": "资料问答", "Check document access": "校验资料访问权限", "Retrieve evidence": "检索资料与业务规则", "Refunds and order changes": "退款与订单修改", "Validate permissions and parameters": "校验业务权限与操作参数", "Obtain required human approval": "按规则确认；不可逆操作由负责人审批", "Shared state: request, evidence, approval, execution result, and handoff context.": "共享状态：请求、依据、审批、执行结果与转人工上下文。", "These paths describe the proposed architecture, not a verified inventory of deployed components.": "架构设计路径；实际交付范围以项目经历为准。", "Answer with sources or hand off": "附来源作答／证据不足时转人工", "Execute once, record, or hand off on failure": "幂等执行并留档／失败转人工", "Architecture analysis": "架构分析", "Future project proposal": "未来项目提案", "Design priority": "设计重点", "Proposed architecture extensions and evaluation plans.": "后续架构方案与评估计划。", "Proposed workflow architecture for document questions and business actions.": "文档问答与业务操作的工作流设计方案。", "Agent scope": "Agent 负责", "Stop condition": "停止条件", "Human decision": "人工介入", "Experience behind this design": "设计的起点", "Document Q&A": "文档问答", "Refund request": "退款请求", "Travel plan": "旅行规划", "Choose a task": "选择任务", "Design boundaries": "设计边界"}};
